def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_pairs(N):
    primes = [i for i in range(2, N + 1) if is_prime(i)]
    pairs = []
    for p in primes:
        q = N - p
        if q > p and q in primes:
            pairs.append((p, q))
    return pairs

